class Solution:
    def totalDistance(self, s):
        rows = 'qwertyuiopasdfghjklzxcvbnm'
        pos = {ch: (i // 10, i % 10) for i, ch in enumerate(rows)}
        r, c = pos['a']
        tot = 0
        for ch in s:
            nr, nc = pos[ch]
            tot += abs(nr - r) + abs(nc - c)
            r, c = nr, nc
        return tot

