        int pr[26], pc[26];
        for (int i = 0; i < 26; i++) { pr[rows[i]-'a'] = i / 10; pc[rows[i]-'a'] = i % 10; }
        int r = pr[0], c = pc[0]; long long tot = 0;
        for (char ch : s) {
            int nr = pr[ch-'a'], nc = pc[ch-'a'];
            tot += abs(nr - r) + abs(nc - c);
            r = nr; c = nc;
        }
        return (int)tot;
    }
};

