class Solution {
    public int totalDistance(String s) {
        String rows = "qwertyuiopasdfghjklzxcvbnm";
        int[] pr = new int[26], pc = new int[26];
        for (int i = 0; i < 26; i++) { pr[rows.charAt(i)-'a'] = i / 10; pc[rows.charAt(i)-'a'] = i % 10; }
        int r = pr[0], c = pc[0], tot = 0;
        for (char ch : s.toCharArray()) {
            int nr = pr[ch-'a'], nc = pc[ch-'a'];
            tot += Math.abs(nr - r) + Math.abs(nc - c);
            r = nr; c = nc;
        }
        return tot;
    }
}

