var totalDistance = function(s) {
    const rows = 'qwertyuiopasdfghjklzxcvbnm';
    const pos = {};
    for (let i = 0; i < 26; i++) pos[rows[i]] = [Math.floor(i/10), i % 10];
    let [r, c] = pos['a'], tot = 0;
    for (const ch of s) {
        const [nr, nc] = pos[ch];
        tot += Math.abs(nr - r) + Math.abs(nc - c);
        r = nr; c = nc;
    }
    return tot;
};
